import { strict as assert } from 'node:assert';
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { existsSync, readFileSync } from 'node:fs';
import { mkdtemp, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { gunzipSync } from 'node:zlib';
import Ajv2020 from 'ajv/dist/2020';
import { parseJson, readJson } from '../../src/cli/output';
import { MAX_OUTPUT_BYTES } from '../../src/cli/runner';

// The fixture corpus of test/fixtures/, generated by scripts/fixtures.mjs from the pinned CLI (task T03). These
// tests check that the corpus is what the later tasks need; `npm run fixtures -- --verify` checks that it is what
// the pinned CLI produces.

const extensionRoot = join(__dirname, '..', '..', '..');
const fixtures = join(extensionRoot, 'test', 'fixtures');
const schemaPath = join(extensionRoot, 'src', 'schemas', 'steward.report-0.1.schema.json');

type Counts = Record<'FAIL' | 'INCOMPLETE' | 'NOT_APPLICABLE' | 'PASS' | 'UNKNOWN', number>;
interface Gate { name: string; evaluated: boolean; eligible: boolean; reason: string; waived: unknown[] }
interface Report {
  schema: string;
  envelope: { tool_version: string };
  verdict: { summary: { counts: Counts }; gates: Gate[]; results: { status: keyof Counts }[] };
}
interface Manifest {
  cli: { version: string; commit: string };
  schema: { path: string; source: string; sha256: string };
  reports: Record<string, { workspace: string; argv: string[]; exit_code: number; report?: string; counts?: Counts;
    gates?: Omit<Gate, 'waived'>[] }>;
  derived: Record<string, { file: string; limit_bytes?: number; bytes_uncompressed?: number }>;
  workspaces: Record<string, { files: Record<string, string> }>;
}

const read = (path: string) => readFileSync(path);
const json = <T>(path: string) => JSON.parse(readFileSync(path, 'utf8')) as T;
const sha256 = (bytes: Buffer) => createHash('sha256').update(bytes).digest('hex');

describe('fixture corpus', () => {
  const manifest = json<Manifest>(join(fixtures, 'manifest.json'));
  const { bioSteward } = json<{ bioSteward: { testedWithCli: string } }>(join(extensionRoot, 'package.json'));
  const validate = new Ajv2020({ strict: false, allErrors: true }).compile<Report>(json(schemaPath));
  const reports = Object.entries(manifest.reports).flatMap(([name, entry]) =>
    entry.report ? [{ name, entry, report: json<Report>(join(fixtures, entry.report)) }] : []);

  it('was generated by the CLI the manifest pins', () => {
    assert.equal(manifest.cli.version, bioSteward.testedWithCli);
    for (const { name, report } of reports) assert.equal(report.envelope.tool_version, bioSteward.testedWithCli, name);
  });

  it('holds a byte-exact copy of the report schema of the pinned release tag', () => {
    const copy = read(schemaPath);
    assert.equal(manifest.schema.path, 'src/schemas/steward.report-0.1.schema.json');
    assert.equal(manifest.schema.source, `v${bioSteward.testedWithCli}:schemas/steward.report-0.1.schema.json`);
    assert.equal(sha256(copy), manifest.schema.sha256);
    // The release tag itself, when `npm run fixtures` has cloned it (F3: the wheel has no schemas).
    const release = join(extensionRoot, '.cli', `release-v${bioSteward.testedWithCli}`);
    if (existsSync(join(release, '.git'))) {
      const tagged = execFileSync('git', ['show', `v${bioSteward.testedWithCli}:schemas/steward.report-0.1.schema.json`],
        { cwd: release });
      assert.ok(copy.equals(tagged), 'the schema copy differs from the release tag');
      console.log(`    Schema copy equals v${bioSteward.testedWithCli}:schemas/steward.report-0.1.schema.json`);
    }
  });

  it('has reports that validate against the schema and match the manifest', () => {
    assert.ok(reports.length >= 8);
    for (const { name, entry, report } of reports) {
      assert.ok(validate(report), `${name}: ${JSON.stringify(validate.errors)}`);
      assert.equal(report.schema, 'steward.report/0.1');
      assert.deepEqual(report.verdict.summary.counts, entry.counts, name);
      const counted: Partial<Counts> = {};
      for (const result of report.verdict.results) counted[result.status] = (counted[result.status] ?? 0) + 1;
      for (const [status, count] of Object.entries(report.verdict.summary.counts)) {
        assert.equal(counted[status as keyof Counts] ?? 0, count, `${name} ${status}`);
      }
      assert.deepEqual(report.verdict.gates.map(({ name: gate, evaluated, eligible, reason }) =>
        ({ name: gate, evaluated, eligible, reason })), entry.gates, name);
      assert.ok(entry.workspace in manifest.workspaces, name);
    }
  });

  it('covers the five statuses, the gate states and both examples (AC-3.1)', () => {
    const statuses = new Set(reports.flatMap(({ report }) => report.verdict.results.map((r) => r.status)));
    assert.deepEqual([...statuses].sort(), ['FAIL', 'INCOMPLETE', 'NOT_APPLICABLE', 'PASS', 'UNKNOWN']);
    const gates = reports.flatMap(({ report }) => report.verdict.gates);
    assert.ok(gates.some((g) => g.evaluated && g.eligible), 'an eligible gate');
    assert.ok(gates.some((g) => g.evaluated && !g.eligible), 'a gate that is not eligible');
    assert.ok(gates.some((g) => !g.evaluated && g.reason === 'partial_check'), 'a partial run');
    for (const base of ['geo', 'toy']) assert.equal(manifest.reports[base].exit_code, 0, base);
    for (const scoped of ['geo-scoped-data', 'geo-scoped-rule']) {
      for (const gate of manifest.reports[scoped].gates ?? []) assert.equal(gate.evaluated, false, scoped);
    }
  });

  it('anchors the seeded FAIL and INCOMPLETE at the files that were changed', () => {
    const anchored = (name: string, status: string, rule: string, path: string) => {
      const report = json<{ verdict: { results: { rule: string; status: string; details: { path?: string }[] }[] } }>(
        join(fixtures, manifest.reports[name].report ?? ''));
      const hit = report.verdict.results.find((r) => r.rule === rule && r.status === status);
      assert.ok(hit, `${name}: ${rule} ${status}`);
      assert.ok(hit.details.some((d) => d.path === path), `${name}: ${rule} names ${path}`);
    };
    anchored('geo-fail-date-symbol', 'FAIL', 'R-83', 'results/top_genes.tsv');
    anchored('geo-incomplete-accession', 'INCOMPLETE', 'R-85', 'paper/data-availability.md');
  });

  it('has derived files that the bounded reader refuses', async () => {
    const report = read(join(fixtures, 'reports', 'geo.json'));
    assert.equal(parseJson(report, validate).kind, 'valid');
    const invalid = read(join(fixtures, manifest.derived['invalid-json'].file));
    assert.ok(report.subarray(0, invalid.length).equals(invalid));
    assert.deepEqual(parseJson(invalid, validate), { kind: 'unreadable' });

    const oversized = manifest.derived.oversized;
    assert.equal(oversized.limit_bytes, MAX_OUTPUT_BYTES);
    const bytes = gunzipSync(read(join(fixtures, oversized.file)));
    assert.equal(bytes.length, oversized.bytes_uncompressed);
    assert.ok(bytes.length > MAX_OUTPUT_BYTES);
    assert.ok(bytes.subarray(0, report.length).equals(report));
    assert.equal(parseJson(bytes, validate, bytes.length).kind, 'valid', 'only its size makes it unreadable');
    const scratch = await mkdtemp(join(tmpdir(), 'steward-fixture-test-'));
    try {
      const file = join(scratch, 'report.json');
      await writeFile(file, bytes);
      assert.deepEqual(await readJson(file, validate), { kind: 'unreadable' });
    } finally {
      await rm(scratch, { recursive: true, force: true });
    }
  });

  it('records a broken steward.toml as the CLI reports it', () => {
    const entry = manifest.reports['geo-broken-config'];
    assert.notEqual(entry.exit_code, 0);
    assert.ok(entry.counts && entry.counts.FAIL >= 1);
  });
});
